class pstring
{
  char data_[32];

public:
  const char *c_str() const;
};

class stash_index_entry
{
  char data_[52];

public:
  void set_name(const pstring &);
};

class AvlNode
{
public:
  AvlNode *left;
  AvlNode *right;
  stash_index_entry *entry;
  stash_index_entry *data() { return entry; }
};

class index_tree
{
public:
  AvlNode *root;
  AvlNode *find(stash_index_entry *);
};

struct substash_record
{
  char padding[716];
  bool stash_file_is_open;
  char align_padding[3];
  index_tree index_tree;
  char tail[68];
};

extern substash_record substash[11];
extern int curstash;
extern void debug_print(const char *, ...);

#define STASHSEARCHREVERSED
#define STASH_LIMIT 11
#define STASH_SYSTEM 0

class stash
{
public:
  static bool file_exists(const pstring &);
};

bool stash::file_exists(const pstring &_name)
{
  stash_index_entry find_me;
  find_me.set_name(_name);

  AvlNode *the_node = 0;
#ifdef STASHSEARCHREVERSED
  for (int i = STASH_LIMIT - 1; i >= STASH_SYSTEM; i--)
#else
  for (int i = STASH_SYSTEM; i < STASH_LIMIT; i++)
#endif
  {
    if (substash[i].stash_file_is_open)
      the_node = substash[i].index_tree.find(&find_me);
    if (the_node)
    {
      curstash = i;
      break;
    }
  }

  if (the_node && the_node->data())
    return true;
  else
  {
#ifndef USER_MKV
    debug_print("%s not found in any stash file", _name.c_str());
#endif
    return false;
  }
}
